from pydantic import BaseModel, Field

class OrderArgs(BaseModel):
    order_id: str = Field(pattern=r"^A\d{4}$")

ORDERS = {"A1001": {"status": "shipped", "total": 42.0}}

def get_order(args):
    a = OrderArgs(**args)
    return ORDERS.get(a.order_id, {"error": "not found"})

def refund(args):
    a = OrderArgs(**args)
    return {"needs_approval": True, "order_id": a.order_id}   # never refund without a person
