def agent(question, max_steps=5):
    messages = [{"role": "user", "content": question}]
    for _ in range(max_steps):
        r = client.messages.create(model="claude-haiku-4-5", max_tokens=400, tools=TOOLS, messages=messages)
        if r.stop_reason != "tool_use":
            return "".join(b.text for b in r.content if b.type == "text")
        messages.append({"role": "assistant", "content": r.content})
        results = []
        for b in r.content:
            if b.type == "tool_use":
                try:
                    out = RUN[b.name](b.input)
                except Exception as e:
                    out = {"error": str(e)}           # errors go back to the model as data
                print("TOOL", b.name, b.input, "->", out)
                results.append({"type": "tool_result", "tool_use_id": b.id, "content": str(out)})
        messages.append({"role": "user", "content": results})
    return "Stopped: step limit reached."

print(agent("Where is order A1001, and can I get a refund?"))
